import{_ as e,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"易纂言卷九","description":"易纂言 - 易纂言卷九","frontmatter":{"title":"易纂言卷九","description":"易纂言 - 易纂言卷九"},"headers":[],"relativePath":"classics/zuanyan/010.md","filePath":"classics/zuanyan/010.md"}'),n={name:"classics/zuanyan/010.md"};function r(c,a,_,i,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言卷九" tabindex="-1">易纂言卷九 <a class="header-anchor" href="#易纂言卷九" aria-label="Permalink to “易纂言卷九”">​</a></h1><p>欽定四庫全書</p><p>元吳澄撰</p><p>文言傳 文言者，彖、爻之辭也。案：繫辭傳曰：其辭文，謂彖、爻之辭，文其言而不質，直言之也。此篇天子所以釋文王、周公之文言，故曰文言傳。繋辭傳者，統論聖人繫辭之意也。文言傳者，詳釋經中文言之辭也。</p><p>「元」者，善之長也；「亨」者，嘉之會也；「利」者，義之和也；貞者，事之幹也。君子體仁足以長人；嘉會足以合禮；利物足以和義；貞固足以幹事。君子行此四德者，故曰：「乾：元亨利貞。」 此一節釋乾彖辭。彖辭本意謂元者亨而利於貞，元言其人，貞言其事，亨利言其佔也。夫子於此釋「元亨利貞」四字，而分為四德，後人因之以配春夏秋冬，以配仁義禮智，皆推廣而言也。「元」如人首，在眾體之上，於時為春，先乎四時，於人為仁，統乎五常，故為眾善之長。「亨」如享禮，萃諸物之珍，於時為夏，萬物茂盛，於人為禮，多儀備具，故為嘉美之會。「利」如刀刃之利，於時為秋，凡物各遂，不相妨害；於人為義，凡事得宜，無所乖戾，故為義之和。「貞」如木身之楨，於時為冬，物皆歸復而有藏；於人為智，物皆辨察而有立，故為事之幹。幹者，木之枝葉所依以立。智之能立事，亦猶是也。項氏曰：「在事之初為善，善之眾盛為嘉，眾得其盛為義，義所成立為事，一理而四名之。」澄案：春秋左氏傳亦載此言，但「善」字作「體」字，彼釋人首之「元」，此則假借「元」字以名天德，故改「體」為「善」。蓋自昔有此訓詁，夫子述之爾。「君子」謂用易之人，法乾之「元」而以仁為體，則善之長在，已可以為人之長矣。「合禮」之「合」如合樂之合，謂會聚備具也。法乾之「亨」而嘉美會聚，則美物眾盛，可以備具乎禮矣。法乾之利而宜利於應物，則可以不乖乎義矣。法乾之貞而智之正，如木楨之固，則可以為事之幹矣。春秋傳無「君子」字，「嘉會」作「嘉德」，此加「君子」字以表用。易者改「德」為「會」，乃與上文協，而得「亨」字之意。君子如是，則為能行此四德，而亦如乾之「元亨利貞」也。 初九曰「潛龍勿用」，何謂也？龍德而隱者也。不易乎世，不成乎名，遁世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。 此一節釋乾初九爻辭。「龍德」，喻聖人之德。「隱」，釋「潛」也。「易」，變移也。成，完全。周，足也。「不易乎世」者，有守於中，不隨時俗而變移也。「不成乎名」者，無願於外，不使聲實之周足也。「遁世」，身隱而不見也。不見是，人不以之為是也。不隨世而易，則不肯以身殉世，故雖隱遁於世而亦無悶。不使其名之成，則不肯以身殉名，故雖不見是於人而亦無悶。「樂則行之」，釋上文「無悶」二句。「憂則違之」，釋上文「不易」、「不成」二句。樂者，謂無悶也。行之，謂為之也。憂者，謂非其所樂也。違之，謂不為也。不求見於世、不求知於人者，此其所樂也，則為之。易乎世、成乎名者，此非其所樂也，則不為。確，堅貌。拔，如拔木之拔，謂其志堅確，不可轉徙而他也。 九二曰：「見龍在田，利見大人。」何謂也？龍，德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化。 此一節釋乾九二爻辭。朱子曰：「正中，不潛而未躍之時也。常言亦信，常行亦謹，盛德之至也。閒邪存其誠，無𭣧亦保之意。」澄謂：中正釋見而在田也。以下卦言，初在下，三在上，二在當其中也。庸言以下，釋大人閒邪，外物不能入也。應物而中不動，故實心不為物所引，而常存於中也。善世以下，利見之意。善於一世而不自驕，德之及人者博，而人皆化。蓋雖居下位而德已著，故世之人利於見之也。 九三曰：「君子終日乾乾，夕惕若，厲，無咎。」何謂也？君子進德修業。忠信，所以進德也；修辭立其誠，所以居業也。知至至之，可與幾也。知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。 此一節釋乾九三爻辭。九二言大人之德，九三言君子之學。「進德修業」，釋「終日乾乾，夕惕若」。「君子終日乾乾」，至夕而猶「惕若」者，何哉？以進其德，修其業也。「進」，謂日新不已。「修」，謂徧舉無遺。「忠信」以下，詳言進修之目。「忠信」者，盡心於中，而達乎在外之信也。心常實，則德無時不進矣。「修辭立其誠」者，修辭於外，而固守其在中之誠也。事皆實，則業無一不修矣。「居」，猶「居貨」之「居」，雖未徧為，而已藏積於此也。「知至」「知終」，知也。「至之終之」，行也。「可與」，猶論語之「可與共」。學先知所至，而行以至之，則自其動之微而趨於善，故曰「可與幾也」。「幾」者，進德之端也。既知所終，而行以終之，則制事之宜皆存於此，故曰「可與存義」也。「存」，猶居也。「義」者，修業之方也。「知至至之，可與幾」，格物致知而誠意也。「知終終之，可與存義」，儘性至命而理於義也。「居上」「在下」，釋「厲」。以下體言，則三居上畫，故曰「上位」。以二體言，則三在下卦，故曰「下位」。「不驕不憂」，釋「無咎」。程子曰：「君子之學如是，故知處上下之道而無驕憂，不懈而知懼，雖在危地而無咎也。」 九四曰「或躍在淵，無咎」，何謂也？上下無常，非為邪也；進退無恆，非離群也。君子進德修業，欲及時也，故無咎。 此一節釋乾九四爻辭。朱子曰：「內卦以德學言，外卦以時位言。進德修業，九三備矣。此則欲其及時而進也。」澄謂：「下」釋「在淵」，「進」釋「躍」，「無常無恆」釋「或」。或則不必其然。故下兼上言，或自淵而天也。進兼退言，或未躍則潛也。下在淵而退潛，上向天而進躍，皆未可必，故曰「無常無恆」。「非為邪，非離群」，釋「無咎」。自下而上以向乎天者，非敢為幹上之邪而不臣也。不退而進，以躍出乎淵者，非欲離在下之群而為君也，時當然爾。平日之進修，固欲其及時也，時之及，則其上進為無咎矣。舜自匹夫之賤，而陟帝位之貴，湯、武去諸侯之卑，而就天子之尊，時之當其可也。舜與湯、武何心焉？豈為邪？離群也哉？ 九五曰：「飛龍在天，利見大人。」何謂也？同聲相應，同氣相求。水流溼，火就燥。雲從龍，風從虎。聖人作而萬物睹。本乎天者親上，本乎地者親下，則各從其類也。 此一節釋乾九五爻辭。鶴鳴而子和，蟲雄鳴而雌應。一雞鳴則眾雞皆鳴，同聲相應也。日，火之精，而取火於日。月，水之精，而取水於月。磁石，鐵之母，而可以引針，同氣相求也。溼者下地，故水之流趨之；燥者乾物，故火之然就之。龍興則致雲，雲從龍也。虎嘯則生風，風從虎也。凡此六者，皆同類相感召。聖人與人亦同類，故作於上而萬物鹹睹。作，起也。物，猶人也。睹，見也。「作」字釋「飛而在天」，「睹」字釋「利見」。程子曰：「龍德升尊位，人之類莫不歸仰。」朱子曰：「本乎天，謂動物；本乎地，謂植物。」澄案：動物首在上，親上也。植物首在下，親下也。先以聲、氣、水、火、雲、風六句為比，而後言聖人作則，人利見之言。又以動植之親上親下，喻利見者之親聖人。亦是諄復之，而以「各從其類」一句，總結上文九句也。或以同聲為震雷巽風之聲，同氣為艮山兌澤之氣，水流溼為坎水趨兌澤，火就燥為離火焚艮山，雲從龍為坎、震，風從虎為巽、離，本乎天為震雷巽風、坎月離日之統於乾，本乎地為坎水離火、艮山兌澤之統於坤。其說陋矣。案：夫子託物廣喻，非取卦象所擬也。 上九曰「亢龍有悔」，何謂也？貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。 此一節釋乾上九爻辭。陽貴陰賤，「貴」，謂九為陽畫也。「無位」者，陽不得陽位也。「高」，謂上居上卦之上也。陽為君，陰為民。「無民」者，純陽無陰也。「賢人」，謂九三。「在下位」，謂在下卦也。敵體而不應上，故上無輔。「貴」，釋九之為龍。「高」，釋上之為「亢」。無位無民，賢人不為之輔，故「有悔」也。然亢者天時，有悔者人事。吉凶悔吝，皆生乎動。亢極之時，宜靜退，不宜動進，動而後有悔也。識時善處者，雖亢而能不動，則亦不至於有悔。洪範言「用作兇」，言靜而不作，亦不兇也。 「潛龍勿用」，下也。「見龍在田」，時舍也。「終日乾乾」，行事也。「或躍在淵」，自試也。「飛龍在天」，上治也。「亢龍有悔」，窮之災也。乾元「用九」，天下治也。 此一節申乾象傳意，下釋「潛」，與象傳同。「時舍」，謂龍之在田，猶在下位，未為時用也。「行事」，謂行其進德修業之事。「試」，猶嘗試之試，自試其可躍而後躍，非必於躍也。「上」謂在天上。「治」，居上而治下也。「窮」謂亢，「災」謂有悔。「亢而有悔」者，時至於窮而有災也。乾元，謂以乾德居元首之尊，用九者則變為柔，以柔濟剛而治天下，故天下治也。 「潛龍勿用」，陽氣潛藏。「見龍在田」，天下文明。「終日乾乾」，與時偕行。「或躍在淵」，乾道乃革。「飛龍在天」，乃位乎天德。「亢龍有悔」，與時偕極。「乾元用九」，乃見天則。 此一節再申象傳意。陽氣潛藏於地中，象傳所謂「陽在下也」。天下見其文明之德而化，象傳所謂「德施普也」。行即行事之行，進德修業，時當如此，故曰「與時偕」。革，謂變革離下而升上也。有天德而位天位，故曰「位乎天德」。極者，窮而止也。三之當行，上之當止，皆因其時，故亦曰「與時偕也」。剛柔適中，天之則也。則者，理之有限節，而無過無不及者也。澄案：此前半章釋一彖六爻已竟，又申繹象傳至再，推演周悉，以見彖爻之辭，義理無窮，縕奧難盡。然獨於乾卦如此者，蓋以六十四卦之首卦，故特致詳焉。以下後半章重釋乾卦彖爻七節，則與第二章釋坤卦彖爻七節相似。 乾元者，始而亨者也；利貞者，性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎！剛健中正，純粹精也。六爻發揮，旁通情也。「時乘六龍」，以御天也；「雲行雨施」，天下平也。 此一節申乾彖傳意。彖傳以</p><p>「大哉乾元，萬物資始，乃統天。雲行雨施，品物流行」五句釋「元亨」。此約其言，謂「乾元」者，始物而能致品物流行之亨者也。彖傳以「乾道變化，各正性命，保合太和，乃利貞」四句釋「利貞」。此約其言，謂「利貞」者，其情無所不利於其性之貞也。又總「元亨利貞」，而以始言「元」，美言「亨」，利天下言「利」，不言所利言「貞」，謂乾始物之元，能以嘉美之亨為利而利天下。但言「利貞」，不言所利之為何事。蓋所包甚大，非止一事之貞而己，故贊之曰「大矣哉」。其曰「大哉乾乎！剛健中正，純粹精者」，又言「元」也。彖傳言「大哉乾元」，此言其所謂「大哉」者，以其德之如是也。剛健而中正，則其剛健無過無不及而不偏。純剛純健，故不雜不駁矣。而中且正焉，則至精之剛健，而非其粗者也。然惟九五足以當之，乾之無九五也。曰「六爻發揮，旁通情」者，又言「貞」也。發，如發矢，揮，如揮手。旁，廣也。通，達也。彖傳以六位時成，言聖人之貞，此言六爻隨其時位，發揮其辭，俾各得其貞者，所以廣達其貞性所利之情也。曰「時乘六龍以御天」者，又言「利」也。彖傳以此一句言聖人之利，而此重言之也。曰「雲行雨施，天下平」者，又言「亨」也。彖傳以「雲行雨施」言天道之亨，以「萬國咸寧」言聖人之亨。此言「天下平」者，即「萬國咸寧」也。 君子以成德為行，日可見之行也。潛之為言也，隱而未見，行而未成，是以君子弗用也。 此一節再釋乾初九爻辭。「成德」，謂內有其實，外有其名，名實兩全，無所虧欠。「行」，謂身之所行。「日可見」，謂顯著於時，當日人皆可得而見。人不可見曰「隱」，人所可見曰「見」。君子若以成德為行，則其所行之行，皆當日人所可見者。初九之潛，隱晦於時，而未顯見，則非所謂日可見之行也。所行內實有餘，外名不足，而未完成，則非所謂以成德為行也。隱而未顯見者，潛之象。行而未完成，是欲其弗用也，故佔雲「勿用」。 君子學以聚之，問以辯之，寬以居之，仁以行之。易曰：「見龍在田，利見大人。」君德也。 此一節再釋乾九二爻辭。前釋初九、九二，皆曰龍德，謂聖人也。再釋皆曰君子，則通學知利行者而言。學，效也。有所未知，則效知者以求知之。蓋理具於心，而散於事物，事物之理有一未明，則心之所具有未盡，必博學周知，俾萬理皆聚而無所闕遺，故曰「學以聚之」。辯，剖決也。既聚矣，必問於先知先覺之人，以剖決其是否，故曰「問以辯之」。「寬」，猶曾子所謂「弘」，張子所謂「大心」也。「居」，謂居業之居。問既辯矣，必有弘廣之量，以藏蓄其所得，故曰「寬以居之」。仁者，心德之全，天理之公也。既有以居之矣，心德渾全，存存不失，應事接物，皆踐其所知，而所行無非天理之公，故曰「仁以行之」。學聚之，以知其理，仁行之，以行其事。問辯之，以審別所當行於學知之後。寬居之，以存貯所已知於仁行之先。寬之所居，即學之所聚者。仁之所行，即問之所辯者。學至於是，則為大人，雖居下位，而其德乃君德也。 九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危無咎矣。 此一節再釋乾九三爻辭。「九三重剛而不中」七字為句，下九四同。「重剛」，謂重乾。九三居下乾之終，接上乾之始；九四居上乾之始，接下乾之終。當重乾上下之際，故皆曰「重剛」。「不中」者，已過九二，未及九五也。「不在天」，則非上卦之中；「不在田」，則非下卦之中，所處在下之上，危地也。以其重剛，用之於學，能乾乾不懈，又因夕之時而惕若知懼，則雖處危地，而無咎也。 九四重剛而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故無咎。 此一節再釋乾九四爻辭。六畫之卦，三與四皆人位也。然九三下履二地，乃人所常居之處；九四上戴五天，在人頭上空虛之間，故曰「中不在人，不在天，不在田」。又不在人，則無依倚停駐之所，故疑而未決。可以至天，則自淵躍出，經由乎四，而遂上於天。若未可至天，則且當在淵而潛，未可望四而躍也。蓋四之位可經過，而非可停駐，必審其可躍而後躍，乃無咎也。 夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶。先天而天弗違，後天而奉天時。天且弗違，而況於人乎？況於鬼神乎？ 此一節再釋乾九五爻辭。九二、九五皆大人。前釋九二盛言其德，釋九五則不言其德，但言人之利見。至此再釋，乃言九五大人之德，與前所釋互相備也。夫天，專言之則道也。此雖兼地言之，而曰天地，然與專言天之一字者同。蓋以其主宰之理而言，非指輕清之氣為天，重濁之質為地也。日月、四時、鬼神，皆天地之氣所為。氣之有象而照臨者為日月，氣之循序而運行者為四時，氣之往來屈伸而生成萬物者為鬼神。命名雖殊，其實一也。其所以明、所以序，所以能吉能兇，皆天地之理主宰之。天地以理言，故曰德。日月、四時、鬼神以氣言，故曰明、曰序、曰吉凶也。程子曰：「天地者，道也。鬼神者，造化之跡也。大人與天地、日月、四時、鬼神合者，合乎道也。」朱子曰：「日月、四時、鬼神，是指形而下者。人與天地、鬼神本無二理，特蔽於有我之私，是以梏於形體而不能相通。大人無私，與道為體，曾何彼此先後之可言哉？先天弗違，謂意之所為，默與道合。後天奉時，謂知理如是，奉而行之。澄謂：人弗能違，故聖人作而皆利見之也。」 「亢」之為言也，知進而不知退，知存而不知亡，知得而不知喪。知進退存亡而不失其正者，其唯聖人乎！ 此一節再釋乾上九爻辭。進退言人事，存亡得喪言時命。得與存之時，進之時也；喪與亡之時，退之時也。但知其得與存而進，不知其喪與亡而退，所以亢也。知進之有退，存之有亡，得之有喪，而處之至當，各得其理之正，則可以不亢而無喪亡之禍矣。故惟聖人能之。「知進退存亡」下不再言得喪者，省文。傳七之一章，凡七百五十六字，釋乾卦彖爻之辭。舊本「何謂也」六句之下，各有「子曰共」十二字，蓋後人所加。「德博而化」之下，有「易曰：見龍在田，利見大人，君德也」十三字，蓋下文重出。「情性也」作「性情」，今依鄭本。「知得而不知喪」之下，有「其唯聖人乎」五字，亦下文重出，安定胡氏以為羨文。長，知兩切，下同。樂音洛。見龍、未見，並賢遍切。庸行、為行之行，並下孟切。幾，平聲。離，力智切。舍音舍。施，時至切。夫，音扶。先天，悉薦切。喪，昔浪切。注身隱而不見曰見。顯見，並賢遍切。子和，苻臥切。乾物，音於。審別，彼列切。夫天，音扶，省文，所梗切。</p><p>坤至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行。 此一節申坤彖傳意。彖傳言至哉坤元，此言其所謂「至哉」者，以其柔靜之至而又剛方也。坤體中含乾陽，如人肺藏之藏氣，故曰至柔；然其氣幾一動而闢之時，乾陽之氣直上而出，莫能御之，故曰「剛」，剛即六二爻辭所謂「直」也。乾運轉不已，而坤體隤然不動，故曰「至靜」；然其生物之德，普徧四周，無處欠缺，故曰「方」，「方」即六二爻辭所謂「方」也。坤之「元」，六二也。「乾」之九五，不徒剛健，而能中正，故為「乾元」之大；坤之六二，不徒柔靜，而能剛方，故為「坤元」之至。彖傳言「後順得常」，此言後則順而得所主，是有坤道之常也。彖傳言「含弘光大」，此言靜翕之時，含萬物生意於中，動闢則化生萬物而光輝也。彖傳言「乃順承天」，此言坤道之順承天之健，而隨天之時以行也。 積善之家，必有餘慶；積不善之家，必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辯之不早辯也。易曰「履霜堅冰至」，蓋言慎也。 此一節釋坤初六爻辭。為善則有福慶，為不善則有禍殃，必然之理也。然皆自小而積，以至於大。小善積而為大善，則福慶亦大而為餘慶；小不善積而為大不善，則禍殃亦大而為餘殃。程子曰：家之所積者善，則福慶及於子孫；所積不善，則災殃流於後世。其大至於弒逆之禍，皆因積累而至，非朝夕所能成也。朝與夕，漸不可長，小積成大，辯之於早，使民下之惡無由而成，乃如履冰之戒也。澄謂：履霜於純坤將用事之初，知陰之始凝而漸盛，堅冰必至於純坤既用事之後也。不善之積，必為大禍殃，亦如此。防幾杜漸者，當慎之於初，不可坐待其由漸而積，以至於極也。 直其正也，方其義也。君子敬以直內，義以方外，敬義立而德不孤。「直、方大，不習無不利」，則不疑其所行也。 此一節釋坤六二爻辭。象辭之所謂直者，言坤體之上下也；方者，言坤體之東西南北也。此就人言之，則直者言其心體之正也，方者言其制事之義也。正之存於中，如物之直而不斜倚；義之應於外，如物之方而不虧缺也。程子曰：君子主敬以直其內，守義以方其外。敬立而內直，義形而外方。義形於外，非在外也。敬義既立，其德盛矣，德不孤也。無所用而不周，無所施而不利，孰為疑乎？朱子曰：「不孤，言大也。」澄謂：兩者對峙之謂立，有敬、直而無義、方，有義乃方而無敬、直則獨而不兩，孤而不可以為大。「敬義兩立，德不孤」，釋直方然後大也。「不疑其所行」，釋「無不利」。 陰雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也。地道無成，而代有終也。 此一節釋坤六三爻辭。項氏曰：「陰雖有美，含之絕句，以含之連下文讀者，非。」澄謂：陽明陰晦，陰雖有章明之美，亦含藏於內而不顯露。陰者為臣之道也。故臣以之而從王事者，不敢居其完全之功。蓋地道但得天道之半，妻道臣道皆然。無成者，無全功也。天始物而地代，天生物以終天之施。代，猶繼也，繼陽之後而終之也。不有其始，但有其終，闕其半而不完全，故曰無成。夫倡於前，妻隨於後，君令於始，臣行於終，是亦無成而代有終也。 天地變化，草木蕃。天地閉，賢人隱。易曰：括囊，無咎無譽。蓋言慎也。 此一節釋坤六四爻辭。上卦為天，下卦為地，上下體不相應，有天地否隔之象。四居上下體之際，故發此義。四變為剛，則如否卦之初六、九四，亦天地不交也。變化，謂天地交而變化生萬物，此以小氣數言一歲之春夏也。閉，謂天地不交而閉塞不相通，此以大氣數言一運之秋冬也。春夏天地變化而草木蕃，秋冬天地閉塞而草木瘁，歲氣然也。盛世君臣和同而賢人出，衰世君臣乖隔而賢人隱，運數然也。各言其一者，互相備也。或雲，皆言運數也，特其盛衰治亂，有似一歲之春夏秋冬爾。「草木蕃」者，召南所謂「朝廷既治，庶類蕃殖」也。「賢人隱」，洪範所謂「百穀不成，俊民用微」也。項氏曰：草禾且蕃，況於人乎？言「盛」者，要其終也。賢人隱，則物從之矣。言衰者，記其始也。程子曰：「天地交感，則變化萬物，草木蕃盛。君臣相際而道亨。天地閉隔，則萬物不𨔵。君臣道絕，賢者隱遁。四於閉隔之時，括囊晦藏，則雖無令譽，可得無咎。言當慎自守也。」 君子黃中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也。 此一節釋坤六五爻辭。爻辭曰「黃裳」，言以中央之色，為下體之飾，以譬君子之德，美在中心，而形見於身為事業也。「黃中」，黃色在中也。「通」，達也。「理」，身之膚腠也。東方青，南方赤，西方白，北方黑，皆偏位，唯中央黃色為正位也。「居體」，居下體也。黃在中而外達於身之膚腠者，以正位之色為裳，而居於身之下體也。「美在其中」，謂「黃中正位」。「暢於四肢」，謂「通理居體」。君子之發於事業，以飾其身，由其中心德美之至也。故自中心而發為飾身之事業，亦如在中黃色之美，而為飾身之裳也。「裳」之所蔽者二足，而言「四支」者，立言之法如此也。項氏曰：「黃中正位，美在其中，屬黃字。」通理居體，暢於四支，屬裳字。 陰疑於陽必戰，為其嫌於無陽也，故稱「龍」焉。猶未離其類也，故稱「血」焉。夫玄黃者，天地之雜也，天玄而地黃。 此一節釋坤上六爻辭。「疑」，如禮記「疑於臣」、「疑於君」、「疑女於夫子」之「疑」，謂與之並也。六陰同類，同類之中，一陰獨疑於陽，五陰其肯從之乎？必與之戰矣。「戰」者，五真陰敵一偽陽也。「坤」本無陽，上六變而為陽，若不稱「龍」，則不見其已變為陽也。雖已變為陽，而本質則陰，故其遭傷也稱血，以見其雖變為陽，而未脫離陰類也。「血」者，陰之傷，而上六之陰，異乎真陰，故其血玄而黃，若真陰，則有黃無玄也。蓋「玄」者，新變為陽之色；「黃」者，舊質為陰之色也。玄黃之血相雜，有天陽之色，又有地陰之色，以見其非臣亦非君也。項氏曰：「玄黃」者，上下無別，所謂雜也。曰「疑於陽」，曰「嫌於無陽」，曰「猶未離其類」，曰「天地之雜」，皆言陰之似陽，臣之似君。楚公子圍之美矣君哉也，然終以野死，則亦何利哉！</p><p>傳七之二章，凡二百五十六字，釋坤卦彖爻之辭。蓋言慎也舊本「慎」作「順」。朱子曰：古字「順」、「慎」通用，此當作慎，言當辯之於微也。今從之。為其雲偽切。離力智切。夫音扶。注漸不可長知兩切。要一遙切。形見見其並賢遍切。無別彼列切。 危者，安其位者也；亡者，保其存者也；亂者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘亂，是以身安而國家可保也。易曰：「其亡其亡，繋於苞桑。」 此一節釋否九五爻辭。自處於危者，乃自安其位之道也。凜乎若將亡將亂者，乃所以常保其存，常有其治也。九五否將休矣，而不忘戒懼如此。蓋於安、存治之時，而能不忘危、亡亂之禍，是以身之位得以安，而國家可保其久存長治也。爻辭亡字，失物之亡，傳所謂亡，亡國亡家之亡。案：繋辭傳明中古聖人憂患之深意，而蔽以一言曰「其辭危」。此傳於乾坤二卦外釋諸爻之辭，而首及「危」之一字，夫子之意，亦文王、周公之意與？ 同人，先號啕而後笑。君子之道，或出或處，或默或語。二人同心，其利斷金。同心之言，其臭如蘭。 此一節釋同人九五爻辭。君子之道，不皆同也。以身之行，則出處或不同；以口之言，則默語或不同。然一人之心既同，則言行不必同，而無能間其同者。故同心者之行，譬如至利之器，可斷至堅之金，無物能梗礙之也。同心者之言，譬如幽生之蘭，自有遠聞之香，無物能障隔之也。九五、六二，其心同一中正，其先暫為三四所間而號啕，其後終得相遇而笑。蓋其心之同，非三四所能梗礙障隔也。 易曰：「自天祐之，吉無不利。」祐者，助也。天之所助者，順也。人之所助者，信也。履信思乎順，又以尚賢也。是以「自天祐之，吉無不利」也。 此一節釋大有上九爻辭。「天」，謂上九。「順」，謂六五得「坤」之柔中。「人」，謂九四。「信」，謂九四剛實。六五履剛實之四，所履者信也。五為心位，能思而得坤中之順，以順上九之陽，「思乎順」也。上九陽剛為賢，而六五尊之在已上，所尚者賢也。六五有履信思順尚賢之德，不但九四之人助之，而上九之天亦助之，是自天而「祐之」也。宜其佔之「吉」，而且「無不利」也。 「勞謙」，君子有終，吉。勞而不伐，有功而不德，厚之至也。語以其功下人者也。德言盛，禮言恭。謙也者，致恭以存其位者也。 此一節釋謙九三爻辭。「勞」，謂竭其力。「勞」者，有功之本。「有功」者，勞之效。「厚之至」，謂非氣量淺薄者所能也。「德言盛」，釋「勞」字。「禮言恭」，釋「謙」字。「言」，助辭，如說卦傳之「說言」、「成言」，詩之「薄言」、「駕言」也。致恭，謂勞而能謙。「存其位」，謂有終而吉。程子曰：「有勞而不自矜伐，有功而不自以為德，是其德弘厚之至也。」言以其功勞而自謙以下於人也。以其德則至盛，以其自處之禮則至恭，所謂謙也。「存」，守也。致其恭巽以守其位，故高而不危，滿而不溢，是以能「終吉」也。夫君子履謙，乃其常行，非謂保其位而為之也。言能致恭，所以能存其位。如言為善有令名，君子豈為令名而為善也哉？亦言有令名者，為善之故也。 知幾其神乎！君子上交不諂，下交不瀆，其知幾乎？幾者，動之微，吉凶之先見者也。君子見幾而作，不俟終日。易曰：「介於石，不終日，貞吉。」介如石焉，寧用終日？斷可識矣。君子知微知彰，知柔知剛，萬夫之望。 此一節釋豫六二爻辭。「知幾」，謂知之於其事未顯著之先，所以為神也。「君子」謂六二，有中正之德也。「上」謂六三，「下」謂初六。六二上比三，下比初。然六二中正，初三柔邪，雖比近而不同，情交而不諂不瀆者也。蓋九四以不中不正為豫樂之主，而三比之，初應之。初、三者，四之黨與也。二中正自守，不肯阿附四之權勢，故雖四之黨與，亦不與之深交者，杜絕阿附之事於幾微之時也。故曰：「其知幾乎？」幾者，動之始，其端眇芒，要終而論。其後或謂六二之貞吉，或謂初、三之兇悔，皆以阿附不阿附而判，所當辨別於始也。其始吉凶雖未顯著，而其端可見矣，故曰「先見者也」。「作」如「作者七人」之作，謂起去而退處也。穆生得免申白之禍者，能見幾而作也。劉、柳竟陷伾文之黨者，不能見幾而作也。二介於三，雖未措足於四之剛，而已知其如石矣。謂三為互坎之下畫，與四同體也。「寧用終日」，謂雖與三比，而不久留於三，速退處二以自守，其見早也。幾動之在先者雖微，而吉凶之先見者則彰。六三之為比者雖柔，而其前之為四者則剛。知所動之微，而已知其後之必彰矣，不待見吉凶而始知其彰也。知所比之柔，而已知其前之有剛矣，不待近九四而始知其剛也。非知幾，其孰能之？程子曰：「見事之幾微者，其見必早。如交於上以恭巽，過則為諂；交於下以和說，過則為瀆。君子見於幾微，故不至於過焉。」幾者，始動之微，吉凶之端，可先見而未著者也。明哲見幾而動，豈俟終日斷別也，其判別可見矣。微與彰、柔與剛相對，君子見微則知彰，見柔則知剛，知幾如是，眾所仰也，故曰「萬夫之望」。 小人不恥不仁，不畏不義，不見利不勸，不威不懲。小懲而大誡，此小人之福也。易曰：「屨校滅趾，無咎。」此之謂也。 此一節釋噬嗑初九爻辭。小人愚下，不知不仁之事為可恥，不知不義之事為可畏，故不誘以利，則不能勸其為善；不懾以威，則不能懲其為惡。噬嗑之初，聽訟之初也。初九為初犯之人，逮捕方至，情實未明，拘以足械，防其走逸而待訊。及其既訊，則無可罪而得釋免。其小人一受小威之懲，因此知恥知畏，以受大刑為戒，而終身不敢為惡，則此一小懲，反為小人之福。所以暫屨滅趾之校，而卒無再犯之咎也。 善不積不足以成名，惡不積不足以滅身。小人以小善為無益而弗為也，以小惡為無傷而弗去也，故惡積而不可掩，罪大而不可解。易曰：「何校滅耳，兇。」 此一節釋噬嗑上九爻辭。為善者必有利益，自小善積為大善，而後成名；為惡者必有害傷，自小惡積為大惡，而後滅身。小人無知，以人之嘗為小善而未成名，則以為無益而弗之為；以已之嘗為小惡而未滅身，則以為無傷而弗之去。於是長惡不悛，犯罪至極。噬嗑之終，聽訟之終也。上為怗終之人，獄辭既具，罪名已定，錮以首械，表其罪犯而待刑。此積成大惡而不復可以揜覆，犯至大罪而不復可以解脫者，所以既荷滅耳之校，而卒受刑誅之兇也。傳文「滅身」之滅，滅，死也。經文「滅耳」之滅，滅，沒也。 顏氏之子，其殆庶幾乎！有不善未嘗不知，知之未嘗復行也。易曰：「不遠復，無祇悔，元吉。」 此一節釋復初九爻辭。項氏曰：殆，將也。庶幾近辭。朱子曰：言近道也。程子曰：顏子無形顯之過，夫子謂其庶幾，未能不勉而中，所欲不逾矩，是有過也。然其明而剛，故一有不善，未嘗不知；既知，未嘗不遽改，乃不遠復也。過既未形而改，何悔之有？復者，陽反來複也。陽，君子之道，故復為反善之義。初陽來複，處卦之初，復之最先，不遠而復者也。失而後有復，唯失之不遠而復，則不至於悔也。 初六，藉用白茅，無咎。苟錯諸地而可矣，藉之用茅，何咎之有？慎之至也。夫茅之為物薄，而用可重也。慎斯術也以往，其無所失矣。 此一節釋大過初六爻辭。苟，猶若也。慎，謹敬也。薄，猶輕也。術，猶道也。大過之時，四陽過盛，初六以卑弱之陰在下，承藉四陽，其謹敬亦過甚。譬之祭物，若但措之於地亦可矣，而必藉之以茅，謹敬之至也。夫茅之為物雖輕，非可重者，而用之以藉祭物，則其用可重也。人能謹敬於此所行之道，則凡事皆無所失矣。蔡氏曰：「天下之事，過則有失，唯過於慎，則無所失，故無咎。」傳七之三章，凡四百四十九字，釋上經八卦九爻之辭。此章並第四章，舊木錯簡在繋辭上下傳二篇中。蓋夫子既釋乾、坤二卦，其餘六十二卦三百七十二爻之辭不能徧釋，故上經釋九爻，下經釋九爻，以發其例，而他爻可以類推，是為文言傳。後人以所釋乾、坤二卦之辭附入本卦，於是所釋上下經十六卦爻辭十八節不能成篇，遂散入繋辭傳，離為三處，顛倒紊亂特甚。如釋大有爻辭內十字，斷簡重出至再。釋乾彖爻既附於乾卦，而釋上九爻辭一節亦復重出，雜於十八節之間，但少「上九曰何謂也」六字，今悉更定。釋否九五、豫六二、噬嗑初九、復初九四處，並增「子曰」字發端。釋同人九五、大有上九、謙九三、大過初九四處，並增「子曰」字，在所引經文之下。唯釋噬嗑上九一節未增，其所增者今刪去。吉凶之先見舊本無兇字。號平聲。斷金東管切。先見陸賢遍切。今讀如字。斷可東亂切。校胡校切。弗去羌呂切。何河可切。復行符後切。藉疾夜切。錯初故切。夫音扶。注意與音餘。之行，言行、常行，並下孟切。間居限切。遠聞音問。說言音曰。夫君子音扶。非為、豈為，並雲偽切。要一遙切。辨別、斷別、判別，並彼列切。和易以豉切。弗之去羌召切。長惡知兩切。悛七全切。不復符後切。覆孚後切。荷河可切。而中貞仲切。</p><p>易曰：「憧憧往來，朋從爾思，天下何思何慮？天下同歸而殊塗，一致而百慮，天下何思何慮？日往則月來，月往則日來，日月相推而明生焉。寒往則暑來，暑往則寒來，寒暑相推而歲成焉。往者屈也，來者信也，屈信相感而利生焉。尺蠖之屈，以求信也；龍蛇之蟄，以存身也；精義入神，以致用也；利用安身，以崇德也。過此以往，未之或知也。窮神知化，德之盛也。」 此一節釋鹹九四爻辭。九四變剛為柔，舍其正應之感，其意憧憧不定，暱於近比之感。四往感五，五因四之感而來感四，私意相感，非此心正理之感也。夫子先言人心定應寂然之感，以明九四憧憧之非；次言天道往來自然之感，以明四、五往來之非也。思者，心之用；慮者，謀度其事也。歸者，所歸之舍；致者，所至之地。皆謂心也。心體虛靈，如止水明鏡，未與物接，寂然不動，何思之有？既與物接，應之各有定理，何慮之有？理之在心者同，因事之不同，而所行之塗各殊；理之在心者一，因事之不一，而所發之慮有百。塗雖殊，慮雖百，而應事之理則同而一也。故定心應事，動而無動，則亦何思何慮之有？此人心定應寂然之感也。若九四之「憧憧」，則豈如是乎？因日之往，而有月之來，因月之往，而有日之來，二曜相推以相繼，則明生而不匱。因寒之往而有暑之來，因暑之往而有寒之來，二氣相推以相代，則歲成而不缺。往者之屈感來者之信，來者之信又感往者之屈，而有明生歲成之利，此天地往來自然之感也。若四、五之往來，則豈如是乎？夫子既以「屈信」二字釋往來之相感，復以物理之屈信、聖學之屈信言之而廣其意。尺蠖不屈，則其行不能伸，既伸而再行，則又屈也。龍蛇不蟄，則其來歲之身不能奮，既奮於來歲，則又蟄也。此物理之屈伸相感也。義理精明，則應物有定，而神不外馳。入者無出，內之屈也，而乃所以致極其外之用，屈之感信也。日用宜利，則每事曲當，而身之所處，隨寓而安，外之信也，而乃所以增崇其內之德，信之感屈也。此聖學之屈信相感也。因言聖學之交相養、互相發，工力至此，則蔑以加矣。過此以往者，為更進而前也。未之或知者，謂非人之所能知也。朱子曰：「自是以上，亦無所用其力矣。至於窮神知化，乃德盛仁熟而自致爾。」澄謂：「窮神者，究竟至此，則心之所存，與天地之心為一。知化者，了悟至此，則身之所行，與天地之事如一。」 作易者，其知盜乎？易曰：「負且乘，致寇至。」負也者，小人之事也；乘也者，君子之器也。小人而乘君子之器，盜思奪之矣。上慢下暴，盜思伐之矣。慢藏誨盜，冶容誨淫。易曰：負且乘，致寇至，盜之招也。 此一節釋解六三爻辭。作易者，作爻辭之聖人也。坎體之陰畫為盜，即爻辭所謂寇也。思，語辭。六三負四乘二，九四為互坎中畫之君，以其互坎下畫之民，據處六三之位而奪之。六三在四之下，而無順戴之恭，慢其上也；在二之上，而有凌乘之僭，暴其下也。故聲其暴慢之罪而伐之。「慢藏誨盜，冶容誨淫」八字，蓋舊有此語，而引之以證六三之招盜。然所招之盜，能奪六三非據之位，能伐六三可罪之惡，其奪之也當，其伐之也有名，亦異乎發藏取貨之盜矣。而謂之寇者，凡可以已而擅興以奪人伐人者，其事雖當，雖有名，亦寇盜也。程於曰：作易者其知盜乎？謂盜者乘釁而至，苟無釁隙，盜安能犯負者而乘，非所安也，故盜乘釁而奪之。滿假而慢上暴下，盜則乘其過惡而伐之。伐者，聲其罪也。貨財而輕慢其藏，是教盜使取之也。女子而天冶其容，是教淫者使暴之也。小人而乘君子之器，是招盜使奪之也。 易曰：公用射隼於高墉之上，獲之，無不利。隼者，禽也。弓矢者，器也。射之者，人也。君子藏器於身，待時而動，何不利之有？動而不括，是以出而有獲，語成器而動者也。 此一節釋解上六爻辭。「翰飛之戾天」者，隼也。三四五互坎為弓，上六變，則上體成離為矢。九四，上卦之君。爻辭所謂公者，射之之人也。君子，即九四也。有弓矢之器在身，必得時至上六而後動者，蓋解以二陽解四陰之難，初、三、五之三陰，已為九二所解矣。上六所居最遠，九二之力，不能及之，九四之力，亦止可以及三陰。唯上六一陰之難未解，待至上六變柔而剛，則成離矢之鏃，而九四之矢鏃，能及上六戾天之隼矣。故九四之動，無所結礙，一齣而能有獲者，待至器成之時而動故也。上六未變，則九四之弓雖具，而矢猶未具，是弓矢二器，未能完全也。上六既變為離，則弓具矢具，而器成矣。括，結礙也。成，完全也。程子曰：「行一身至於天下之事，苟無其器，與不以時而動，小則括塞，大則喪敗。自古喜有為而無成功，或顛覆者，皆由是也。」 天地絪縕，萬物化醇。男女構精，萬物化生。易曰：「三人行，則損一人；一人行，則得其友。」言致一也。 此一節釋損六三爻辭。凡物之相合，可二而不可三。蓋以一合一，則其情專；以一合二，則其情分。故三人行則有餘，而當損其一；一人行則無對，而當益其一。然後二人相與，其情專致於一而不二乎他也。夫子因以天地之陰陽、男女之牝牡言之。絪縕者，氣之交也。構精者，形之交也。天地之二氣交，故物之以氣化者，其氣醲厚而能醇。男女之二形交，故物之以形化者，其精凝聚而能生。此氣形之相皆交以二，與三人損一、一人得友之義合。蓋二者其理同，言其以一合一，故能致一而不二也。 君子安其身而後動，易其心而後語，定其交而後求。君子修此三者，故全也。危以動，則民不興也。懼以語，則民不應也。無交而求，則民不與也。莫之與，則傷之者至矣。易曰：「莫益之，或擊之，立心勿恆，兇。」 此節釋益上九爻辭。「安其身」，謂循理則身康安。「動」，謂由已及物，以變動其民也。「易其心」，謂闕志則心和易。「語」，謂由中達外，以告語其民也。「定」者，前定。「交」者，下交。「於民」，謂先施於民以固結之。「求」猶責也，謂責其愛戴歸向也。「修」，謂安身、易心、定交三者皆無缺全，謂民興起而與之也。欲勝理則身多危，而不足以率人，故動之而民不興喜。氣勝志則心多懼，而不足以感人，故語之而民不應合。「無交而求，則民弗與」者，無以固結其民於先，而求其報上，則民不助之也。「益」者，以上益下。上九之君，當益六三之民，今不能利益其民，乃或有時而擊害其民，是上之先施者，無以交結其民，而求民之報上，則民之所報，亦如君之所施者矣。君莫益其民，而民亦莫與其君；君或擊其民，而民亦或傷其君。民莫之與，而傷之者至，此曾子所謂「出乎爾者反乎爾」，孟子所謂「民今而後能反之」者也。上九無益民之心，而或有害民之心，當速改變，此心不可恆也。故爻辭戒之曰：「立心勿恆。」「莫益之，或擊之」之義，尤足示訓戒者，故夫子發明君民施報之理如此。蓋因經文「兇」字而生出此意也。釋爻辭，但取「定其交」一句，因泛及「安其身」、「易其心」二句耳。 易曰：「困於石，據於蒺藜，入於其宮，不見其妻，兇。」非所困而困焉，名必辱；非所據而據焉，身必危。既辱且危，死其將至，妻其可得見邪？ 此一節釋困六三爻辭。非所困，非所據，謂六三不當乘九二也。六三以不中不正之柔，乘九二剛中之上，其周官所謂罷民之有過惡者與？「困於石」者，過惡猶輕，而坐於嘉石者也。或三日，或五日，或七日，或九日，或旬有三日而免。未麗於法，恥之而已矣，故曰名辱。「據於蒺藜」者，過惡加重，而置於叢棘者也。入圜土，收教之，能改者，或一年，或二年，或三年而舍，不能改而出圜土者殺。已麗於法，刑罰將及矣，故曰身危。先困辱於坐石，後據危於蒺藜，由辱而至危，非能改其過惡者，必至於死，故曰「死其將至」。「其」者，將然之辭。雖暫還家，而妻已離異，故曰妻其可得見邪。詳見經注及象傳注。 德薄而位尊，知小而謀大，力小而任重，鮮不及矣。易曰：「鼎折足，覆公餗，其刑剭，兇。」言不勝其任也。 此一節釋鼎九四爻辭。九四陽畫離體，而與初正應。陽剛有德者也，而居柔，則其德薄矣。上體而近君，則其位尊也。離明有知者也，而未中，則其知小矣。三牲而大烹，則其謀大也。德知在已，力資乎人者也。初六正應而柔弱，則其力小矣。鼎重器，而有公餗實之，則其任重也。有大德者，職位可以尊，德薄則不足以稱其位矣。有大知者，圖謀可以大，知小則不足以周其謀矣。有大功者，負任可以重，力小則不足以勝其任矣。德不稱其位，知不周其謀，力不勝其任，則鮮有不及禍者。程子曰：「四下應初，初陰柔不勝任，猶鼎之折足，覆公上之餗也。」澄案：釋爻辭取力小而任重之義，因及前二句爾。 不出戶庭，無咎。亂之所生也，則言語以為階。君不密則失臣，臣不密則失身，幾事不密則害成，是以君子慎密而不出也。 此一節釋節初九爻辭。初九當節之初，慎守其正而不輕動，猶人在內而不輕出至戶外之庭。夫子以為人之慎言而不輕出諸口者，亦當如是。「階」，猶雲所由也。禍亂之所生，每由於言語。君不慎密其言，則臣或受禍，而因此遂失其臣；臣不慎密其言，則身或受禍，而因此遂失其身。幾密之事，未彰於外，不可使人知者，若不慎密其言，則或至漏洩，而因此遂成患害。是以君子慎密其言而不敢輕出者，節之也。此爻辭所象慎動之節，而夫子以發言之辭釋之。程子曰：「在其所節，惟言與行。節於言，則行可知，言當在先也。」 鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。君子居其室，出其言善，則千里之外應之，況其邇者乎？居其室，出其言不善，則千里之外違之，況其邇者乎？言出乎身，加乎民；行發乎邇，見乎遠。言行，君子之樞機。樞機之發，榮辱之主也。言行，君子之所以動天地也，可不慎乎！ 此一節釋中孚九三爻辭。「鳴鶴」，謂九。「在陰」，謂二。君子居室，猶鶴之在陰也。出言之善，猶鶴之鳴也。「千里之外應之」，謂九二遠得九五之應也。「況其邇者乎」，謂九二近得六三之和也。若其出言之不善，則反是，遠不孚而近亦不孚矣，何以有九五之應、六三之和哉？「言出乎身，加乎民」，釋「鳴鶴在陰，其子和之」二句。言者，九二之鳴也。「出乎身」，釋「鶴在陰」，謂其言肇起於二也。二剛，畫鶴之身也。「加乎民」，釋「子和之」，謂其言及於三也。三柔，畫二之民也。「行發乎邇，見乎遠。」釋「我有好爵，吾與爾靡之」二句。行者，九五之好爵也。「發乎邇」，釋「我有」，謂其行先達於四也。四近比，故曰「邇」也。「見乎遠」，釋「爾靡之」，謂其行形著於二也。二應位，故曰「遠」也。二、五以中實相感應，故九二近得六三同體之孚，而遠得九五同德之孚。九五近得六四同體之孚，而遠得九二同德之孚也。樞，門棖。機，弩牙也。樞一發而扉動，機一發而矢去。言行之發，有善不善，而遠近之應與違各異。應主榮，違主辱，亦猶扉動而有開闔，矢去而有中否也。言行不唯可以動人，而又可以動天地。君子豈可不慎其言行，而出善言善行乎？九二之言，近感三而遠感五，誠之動人而上動乎天也。九五之行，近感四而遠感二，誠之動人而下動乎地也。天地非有二，地亦天也，以卦位上下分屬則如此爾。</p><p>傳七之四章，九六百一十九字，釋下經八卦九爻之辭。舊本釋鹹九四、解上六、困六三、節初九、中孚九二五處，並增「子曰」字，在所引經之下，釋解六三、益上九、鼎九四三處，並增「子曰」字。發端唯釋損六三一節未增，其所增者，今刪去。則民不興也，「興」作「與」。今案：「與」字與下文重「興」字，則「興」應韻葉。死其將至，「其」作「期」，今從陸氏釋文本及東萊呂氏音訓所定。其刑剭，俗本作「形渥」，說見經注。乘平聲。信音伸，並同。藏，木浪切。射，食亦切。易其心，以豉切。知小音智。鮮，仙展切。折，之設切。勝音升。子和，胡臥切。靡，蒙池切。見，賢遍切。行，下孟切。後同注。舍其音舍。近，比皮二切。謀度，待洛切。難，奴旦切。喪敗去聲。施報，時至切。罷民音皮。稱，充證切。為比，雲偽切。 易纂言卷九</p>',10)])])}const m=e(n,[["render",r]]);export{f as __pageData,m as default};
